-- Layercake.usp_report_employer_scheme_coverage (src/sql/Layercake/Procedures/Layercake.usp_report_employer_scheme_coverage.sql)
CREATE OR ALTER PROCEDURE Layercake.usp_report_employer_scheme_coverage
    @as_of_date date = NULL
AS
/*
    Count-only employer coverage (REQ-013, RULE-060), one row per Campaign Year and payer type
    that has a paid member.
    - Paid member: a Layercake.silv_payment_events row (contact_no, campaign_year). Payer type
      from that year's silv_member_year_attributes row; a year with no attributes row is
      0 Unknown, and Unknown is reported as its own row (ASM-006).
    - Scheme-link employer: a live corporate subscription for the same Campaign Year
      (brnz_corporate_subscription, _is_deleted 0, sub_status and sub_user_status 'Active', Q-027)
      whose scheme_no matches a CE.vwCorporateSchemes.apuk_subscriptionnumber row with an
      AccountNumber. Checked for every payer type.
    - Contact-record employer: a CE.vwContact row for the contact whose ParentCustomerId is set
      and whose ParentCustomerIdType is 'account' (ASM-006 (3)).
    A member with both sources counts in both columns; no_employer counts members with neither.
    Coverage = count / paid_members x 100 (answers.md, MOD-014 coverage columns).
    Each member is counted once per year (EXISTS), however many scheme or contact rows match.
    @as_of_date is accepted and ignored: every report takes one (ADR-003); coverage covers every year.
    Aggregates only (RULE-064).
*/
BEGIN
    SET NOCOUNT ON;

    WITH member_years AS (
        SELECT
            pe.campaign_year,
            ISNULL(ya.payer_type_id, 0) AS payer_type_id,
            CASE
                WHEN EXISTS (
                    SELECT 1
                    FROM Layercake.brnz_corporate_subscription AS cs
                    INNER JOIN CE.vwCorporateSchemes AS sc
                        ON sc.apuk_subscriptionnumber = cs.scheme_no
                    WHERE cs.contact_no = pe.contact_no
                        AND cs.sub_campaign_year = pe.campaign_year
                        AND cs._is_deleted = 0
                        AND cs.sub_status = N'Active'
                        AND cs.sub_user_status = N'Active'
                        AND sc.AccountNumber IS NOT NULL
                ) THEN 1
                ELSE 0
            END AS has_scheme_link,
            CASE
                WHEN EXISTS (
                    SELECT 1
                    FROM CE.vwContact AS ct
                    WHERE ct.Rics_contactno = pe.contact_no
                        AND ct.ParentCustomerIdType = N'account'
                        AND ct.ParentCustomerId IS NOT NULL
                ) THEN 1
                ELSE 0
            END AS has_contact_record
        FROM Layercake.silv_payment_events AS pe
        LEFT JOIN Layercake.silv_member_year_attributes AS ya
            ON ya.contact_no = pe.contact_no
            AND ya.campaign_year = pe.campaign_year
    ),

    year_counts AS (
        SELECT
            my.campaign_year,
            my.payer_type_id,
            COUNT(*) AS paid_members,
            SUM(my.has_scheme_link) AS scheme_link_employer,
            SUM(my.has_contact_record) AS contact_record_employer,
            SUM((1 - my.has_scheme_link) * (1 - my.has_contact_record)) AS no_employer
        FROM member_years AS my
        GROUP BY my.campaign_year, my.payer_type_id
    )

    SELECT
        yc.campaign_year,
        pt.payer_type_name,
        yc.paid_members,
        yc.scheme_link_employer,
        yc.contact_record_employer,
        yc.no_employer,
        CAST(
            ROUND(100.0 * yc.scheme_link_employer / yc.paid_members, 1) AS decimal(5, 1)
        ) AS scheme_link_coverage_pct,
        CAST(
            ROUND(100.0 * yc.contact_record_employer / yc.paid_members, 1) AS decimal(5, 1)
        ) AS contact_record_coverage_pct
    FROM year_counts AS yc
    INNER JOIN Layercake.silv_ref_payer_type AS pt
        ON pt.id = yc.payer_type_id
    ORDER BY yc.campaign_year, yc.payer_type_id;
END;
GO
-- Layercake.usp_report_employer_source_agreement (src/sql/Layercake/Procedures/Layercake.usp_report_employer_source_agreement.sql)
CREATE OR ALTER PROCEDURE Layercake.usp_report_employer_source_agreement
    @as_of_date date = NULL
AS
/*
    Count-only agreement between the two employer sources (REQ-013, RULE-060), one row per
    Campaign Year that has a paid member with an employer from both sources.
    - Paid member: a Layercake.silv_payment_events row (contact_no, campaign_year), counted per
      contact-year, any payer type (ASM-006 (4)).
    - Scheme-link firm: apuk_onbehalfoforganisationid of a CE.vwCorporateSchemes row with an
      AccountNumber whose apuk_subscriptionnumber is the scheme_no of a live corporate
      subscription for that year (_is_deleted 0, 'Active'/'Active', Q-027): the same
      scheme link the coverage report counts.
    - Contact-record firm: CE.vwContact.ParentCustomerId where ParentCustomerIdType is 'account'.
    - Same firm: the account GUIDs are equal, never the names (ASM-006 (3)). A member with
      several scheme or contact firms in the year is the same firm when any pair is equal.
    agreement_rate_pct = same_firm / both_sources x 100.
    @as_of_date is accepted and ignored: every report takes one (ADR-003).
    Aggregates only (RULE-064).
*/
BEGIN
    SET NOCOUNT ON;

    WITH scheme_firms AS (
        SELECT DISTINCT
            cs.contact_no,
            cs.sub_campaign_year AS campaign_year,
            sc.apuk_onbehalfoforganisationid AS account_id
        FROM Layercake.brnz_corporate_subscription AS cs
        INNER JOIN CE.vwCorporateSchemes AS sc
            ON sc.apuk_subscriptionnumber = cs.scheme_no
        WHERE cs._is_deleted = 0
            AND cs.sub_status = N'Active'
            AND cs.sub_user_status = N'Active'
            AND sc.AccountNumber IS NOT NULL
    ),

    contact_firms AS (
        SELECT DISTINCT
            ct.Rics_contactno AS contact_no,
            ct.ParentCustomerId AS account_id
        FROM CE.vwContact AS ct
        WHERE ct.ParentCustomerIdType = N'account'
            AND ct.ParentCustomerId IS NOT NULL
    ),

    member_years AS (
        SELECT
            pe.campaign_year,
            CASE
                WHEN EXISTS (
                    SELECT 1
                    FROM scheme_firms AS sf
                    WHERE sf.contact_no = pe.contact_no
                        AND sf.campaign_year = pe.campaign_year
                )
                AND EXISTS (
                    SELECT 1
                    FROM contact_firms AS cf
                    WHERE cf.contact_no = pe.contact_no
                ) THEN 1
                ELSE 0
            END AS has_both,
            CASE
                WHEN EXISTS (
                    SELECT 1
                    FROM scheme_firms AS sf
                    INNER JOIN contact_firms AS cf
                        ON cf.contact_no = sf.contact_no
                        AND cf.account_id = sf.account_id
                    WHERE sf.contact_no = pe.contact_no
                        AND sf.campaign_year = pe.campaign_year
                ) THEN 1
                ELSE 0
            END AS is_same_firm
        FROM Layercake.silv_payment_events AS pe
    ),

    year_counts AS (
        SELECT
            my.campaign_year,
            SUM(my.has_both) AS both_sources,
            SUM(my.is_same_firm) AS same_firm
        FROM member_years AS my
        GROUP BY my.campaign_year
        HAVING SUM(my.has_both) > 0
    )

    SELECT
        yc.campaign_year,
        yc.both_sources,
        yc.same_firm,
        yc.both_sources - yc.same_firm AS different_firm,
        CAST(ROUND(100.0 * yc.same_firm / yc.both_sources, 1) AS decimal(5, 1)) AS agreement_rate_pct
    FROM year_counts AS yc
    ORDER BY yc.campaign_year;
END;
GO
-- Layercake.usp_report_top_employers (src/sql/Layercake/Procedures/Layercake.usp_report_top_employers.sql)
CREATE OR ALTER PROCEDURE Layercake.usp_report_top_employers
    @as_of_date date = NULL
AS
/*
    Count-only top employers (REQ-013, RULE-061, RULE-062; Q-010): paid members per firm in the
    last full Campaign Year, the 25 firms with the most, ties broken by employer_account_number
    (ascending) so the list is the same on every run.
    - Last full Campaign Year: the ref_campaign_year_config year before the one covering
      @as_of_date (NULL = today, ADR-003). The report fails if no year covers the date or none
      precedes it.
    - Paid member: a silv_payment_events row for that year with payer type 2 Corporate or
      1 Individual in silv_member_year_attributes. 0 Unknown (and the other reserved ids) is left
      out, so corporate + individual = paid_members; the coverage report counts them.
    - Corporate member: its scheme-link firm (CE.vwCorporateSchemes AccountNumber / AccountName
      of a live subscription's scheme for that year, Q-027); with no scheme link, its
      contact-record firm, still in the corporate column.
    - Individual member: its contact-record firm (CE.vwContact.ParentCustomerId of type 'account'
      to CE.vwAccount AccountNumber / name).
    - A member counts once: where it has several scheme firms the lowest scheme_no, then the lowest
      AccountNumber, wins (as corporate_account_ref takes the lowest scheme_no, Q-036); where it
      has several contact-record firms the lowest AccountNumber wins.
    A firm's name is the highest of the names its members carry, should the two sources differ.
    A member with no firm is not listed. Aggregates only (RULE-064).
*/
BEGIN
    SET NOCOUNT ON;

    DECLARE @report_date date = ISNULL(@as_of_date, CAST(SYSDATETIME() AS date));
    DECLARE @last_full_year int;

    SELECT @last_full_year = MAX(prev.campaign_year)
    FROM Layercake.ref_campaign_year_config AS cur
    INNER JOIN Layercake.ref_campaign_year_config AS prev
        ON prev.campaign_year < cur.campaign_year
    WHERE @report_date BETWEEN cur.campaign_year_start AND cur.campaign_year_end;

    IF @last_full_year IS NULL
        THROW 50014, N'usp_report_top_employers: no Campaign Year before the one covering @as_of_date in Layercake.ref_campaign_year_config.', 1;

    WITH members AS (
        SELECT
            pe.contact_no,
            ya.payer_type_id
        FROM Layercake.silv_payment_events AS pe
        INNER JOIN Layercake.silv_member_year_attributes AS ya
            ON ya.contact_no = pe.contact_no
            AND ya.campaign_year = pe.campaign_year
        WHERE pe.campaign_year = @last_full_year
            AND ya.payer_type_id IN (1, 2)
    ),

    scheme_firms AS (
        SELECT
            cs.contact_no,
            sc.AccountNumber AS account_number,
            sc.AccountName AS account_name,
            ROW_NUMBER() OVER (
                PARTITION BY cs.contact_no
                ORDER BY cs.scheme_no, sc.AccountNumber
            ) AS firm_rank
        FROM Layercake.brnz_corporate_subscription AS cs
        INNER JOIN CE.vwCorporateSchemes AS sc
            ON sc.apuk_subscriptionnumber = cs.scheme_no
        WHERE cs.sub_campaign_year = @last_full_year
            AND cs._is_deleted = 0
            AND cs.sub_status = N'Active'
            AND cs.sub_user_status = N'Active'
            AND sc.AccountNumber IS NOT NULL
    ),

    contact_firms AS (
        SELECT
            ct.Rics_contactno AS contact_no,
            ac.AccountNumber AS account_number,
            ac.name AS account_name,
            ROW_NUMBER() OVER (
                PARTITION BY ct.Rics_contactno
                ORDER BY ac.AccountNumber
            ) AS firm_rank
        FROM CE.vwContact AS ct
        INNER JOIN CE.vwAccount AS ac
            ON ac.AccountId = ct.ParentCustomerId
        WHERE ct.ParentCustomerIdType = N'account'
            AND ac.AccountNumber IS NOT NULL
    ),

    member_firms AS (
        SELECT
            m.payer_type_id,
            CASE
                WHEN sf.account_number IS NOT NULL THEN sf.account_number
                ELSE cf.account_number
            END AS employer_account_number,
            CASE
                WHEN sf.account_number IS NOT NULL THEN sf.account_name
                ELSE cf.account_name
            END AS employer_name
        FROM members AS m
        LEFT JOIN scheme_firms AS sf
            ON sf.contact_no = m.contact_no
            AND sf.firm_rank = 1
            AND m.payer_type_id = 2
        LEFT JOIN contact_firms AS cf
            ON cf.contact_no = m.contact_no
            AND cf.firm_rank = 1
    ),

    firm_counts AS (
        SELECT
            mf.employer_account_number,
            MAX(mf.employer_name) AS employer_name,
            SUM(CASE WHEN mf.payer_type_id = 2 THEN 1 ELSE 0 END) AS corporate_paid_members,
            SUM(CASE WHEN mf.payer_type_id = 1 THEN 1 ELSE 0 END) AS individual_paid_members,
            COUNT(*) AS paid_members
        FROM member_firms AS mf
        WHERE mf.employer_account_number IS NOT NULL
        GROUP BY mf.employer_account_number
    )

    SELECT TOP (25)
        fc.employer_account_number,
        fc.employer_name,
        fc.corporate_paid_members,
        fc.individual_paid_members,
        fc.paid_members
    FROM firm_counts AS fc
    ORDER BY fc.paid_members DESC, fc.employer_account_number ASC;
END;
GO
